from functools import wraps
from time import perf_counter

def medir_tiempo(funcion):
    @wraps(funcion)
    def envoltura(*args, **kwargs):
        inicio = perf_counter()
        resultado = funcion(*args, **kwargs)
        print(f'Tardó {perf_counter() - inicio:.6f}s')
        return resultado
    return envoltura

@medir_tiempo
def sumar(a, b):
    return a + b

print(sumar(2, 3))

from functools import wraps

def repetir(veces):
    def decorador(funcion):
        @wraps(funcion)
        def envoltura(*args, **kwargs):
            resultado = None
            for _ in range(veces):
                resultado = funcion(*args, **kwargs)
            return resultado
        return envoltura
    return decorador

@repetir(3)
def avisar():
    print('Hola')

class Recurso:
    def __enter__(self):
        print('Abrir recurso')
        return self

    def __exit__(self, tipo, valor, traza):
        print('Cerrar recurso')
        return False

with Recurso() as recurso:
    print('Usar recurso')
